#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define MAXN 100
#define EPS 1e-9

typedef struct {
    double x, y;
} Point2D;

int n1, n2;
Point2D poly1[MAXN], poly2[MAXN];

double min(double a, double b) { return a < b ? a : b; }
double max(double a, double b) { return a > b ? a : b; }

// Get y-range of poly1 at given x (assuming convex polygon)
void getYRange(double x, double *ymin, double *ymax) {
    *ymin = 1e100;
    *ymax = -1e100;
    for (int i = 0; i < n1; i++) {
        int j = (i+1) % n1;
        double x1 = poly1[i].x, y1 = poly1[i].y;
        double x2 = poly1[j].x, y2 = poly1[j].y;
        if (fabs(x2 - x1) < EPS) {
            if (fabs(x - x1) < EPS) {
                *ymin = min(*ymin, min(y1, y2));
                *ymax = max(*ymax, max(y1, y2));
            }
        } else {
            double t = (x - x1) / (x2 - x1);
            if (t >= -EPS && t <= 1+EPS) {
                double y = y1 + t*(y2 - y1);
                *ymin = min(*ymin, y);
                *ymax = max(*ymax, y);
            }
        }
    }
}

// Get z-range of poly2 at given x
void getZRange(double x, double *zmin, double *zmax) {
    *zmin = 1e100;
    *zmax = -1e100;
    for (int i = 0; i < n2; i++) {
        int j = (i+1) % n2;
        double x1 = poly2[i].x, z1 = poly2[i].y;
        double x2 = poly2[j].x, z2 = poly2[j].y;
        if (fabs(x2 - x1) < EPS) {
            if (fabs(x - x1) < EPS) {
                *zmin = min(*zmin, min(z1, z2));
                *zmax = max(*zmax, max(z1, z2));
            }
        } else {
            double t = (x - x1) / (x2 - x1);
            if (t >= -EPS && t <= 1+EPS) {
                double z = z1 + t*(z2 - z1);
                *zmin = min(*zmin, z);
                *zmax = max(*zmax, z);
            }
        }
    }
}

int main() {
    scanf("%d", &n1);
    for (int i = 0; i < n1; i++)
        scanf("%lf %lf", &poly1[i].x, &poly1[i].y);
    scanf("%d", &n2);
    for (int i = 0; i < n2; i++)
        scanf("%lf %lf", &poly2[i].x, &poly2[i].y);

    // Find x-range that both polygons cover
    double minX1 = 1e100, maxX1 = -1e100;
    for (int i = 0; i < n1; i++) {
        if (poly1[i].x < minX1) minX1 = poly1[i].x;
        if (poly1[i].x > maxX1) maxX1 = poly1[i].x;
    }
    double minX2 = 1e100, maxX2 = -1e100;
    for (int i = 0; i < n2; i++) {
        if (poly2[i].x < minX2) minX2 = poly2[i].x;
        if (poly2[i].x > maxX2) maxX2 = poly2[i].x;
    }
    double xmin = max(minX1, minX2);
    double xmax = min(maxX1, maxX2);

    if (xmin >= xmax - EPS) {
        printf("0.000000\n");
        return 0;
    }

    // Numerical integration along x using Simpson's rule
    int steps = 1000000;
    double h = (xmax - xmin) / steps;
    double volume = 0.0;
    for (int i = 0; i <= steps; i++) {
        double x = xmin + i * h;
        double ymin, ymax, zmin, zmax;
        getYRange(x, &ymin, &ymax);
        getZRange(x, &zmin, &zmax);
        double area = (ymax - ymin) * (zmax - zmin);
        if (i == 0 || i == steps)
            volume += area;
        else if (i % 2 == 1)
            volume += 4 * area;
        else
            volume += 2 * area;
    }
    volume *= h / 3.0;
    printf("%.6f\n", volume);
    return 0;
}

