#define MAXN 105

double px1[MAXN], py1[MAXN]; int n1;
double px2[MAXN], py2[MAXN]; int n2;

// Get the width (max-min of second coord) of convex polygon at given first coord x
// polygon vertices: px[], py[], n vertices
double getWidth(double *px, double *py, int n, double x, double *lo, double *hi) {
    *lo = 1e18; *hi = -1e18;
    int found = 0;
    for (int i = 0; i < n; i++) {
        int j = (i+1)%n;
        double x1=px[i], x2=px[j], y1=py[i], y2=py[j];
        if ((x1<=x && x<=x2)||(x2<=x && x<=x1)) {
            if (fabs(x2-x1)<1e-12) {
                double mn = y1<y2?y1:y2, mx=y1>y2?y1:y2;
                if (mn < *lo) *lo=mn;
                if (mx > *hi) *hi=mx;
            } else {
                double t=(x-x1)/(x2-x1);
                double y=y1+t*(y2-y1);
                if (y<*lo)*lo=y;
                if (y>*hi)*hi=y;
            }
            found=1;
        }
    }
    if (!found||*hi<*lo) return 0;
    return *hi - *lo;
}

