#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define EPS 1e-10

typedef struct {
    double x, y;
} Point;

static int cmp_double(const void *a, const void *b) {
    double x = *(const double *)a;
    double y = *(const double *)b;
    if (x < y - EPS) return -1;
    if (x > y + EPS) return 1;
    return 0;
}

static double polygon_area(Point *p, int n) {
    double s = 0.0;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        s += p[i].x * p[j].y - p[j].x * p[i].y;
    }
    return fabs(s) * 0.5;
}

/* 
   For a convex polygon, compute the vertical intersection length with line x = X:
   i.e. length of { y | (X,y) is inside polygon }.
   Returns 0 if no intersection.
*/
static double vertical_width(Point *p, int n, double X) {
    double ys[256];
    int cnt = 0;

    for (int i = 0; i < n; i++) {
        Point a = p[i];
        Point b = p[(i + 1) % n];

        if (fabs(a.x - b.x) < EPS) {
            if (fabs(X - a.x) < EPS) {
                ys[cnt++] = a.y;
                ys[cnt++] = b.y;
            }
        } else {
            double minx = a.x < b.x ? a.x : b.x;
            double maxx = a.x > b.x ? a.x : b.x;
            if (X + EPS < minx || X - EPS > maxx) continue;

            double t = (X - a.x) / (b.x - a.x);
            if (t < -EPS || t > 1.0 + EPS) continue;
            double y = a.y + t * (b.y - a.y);
            ys[cnt++] = y;
        }
    }

    if (cnt == 0) return 0.0;

    qsort(ys, cnt, sizeof(double), cmp_double);

    /* remove duplicates caused by touching vertices / vertical edges */
    double uniq[256];
    int m = 0;
    for (int i = 0; i < cnt; i++) {
        if (m == 0 || fabs(ys[i] - uniq[m - 1]) > 1e-8) {
            uniq[m++] = ys[i];
        }
    }

    if (m < 2) return 0.0;
    return uniq[m - 1] - uniq[0];
}

static double f(Point *p1, int n1, Point *p2, int n2, double x) {
    double w1 = vertical_width(p1, n1, x);
    double w2 = vertical_width(p2, n2, x);
    return w1 * w2;
}

int main(void) {
    int n1, n2;

    while (scanf("%d", &n1) == 1 && n1) {
        Point p1[128], p2[128];
        double xs[512];
        int xc = 0;

        for (int i = 0; i < n1; i++) {
            scanf("%lf %lf", &p1[i].x, &p1[i].y);
            xs[xc++] = p1[i].x;
        }

        scanf("%d", &n2);
        for (int i = 0; i < n2; i++) {
            scanf("%lf %lf", &p2[i].x, &p2[i].y); /* here y actually means z */
            xs[xc++] = p2[i].x;
        }

        qsort(xs, xc, sizeof(double), cmp_double);

        double ux[512];
        int m = 0;
        for (int i = 0; i < xc; i++) {
            if (m == 0 || fabs(xs[i] - ux[m - 1]) > 1e-8) {
                ux[m++] = xs[i];
            }
        }

        double ans = 0.0;

        /* On each interval between consecutive x-coordinates of vertices,
           each width is linear, so product is quadratic.
           Simpson's rule is exact for quadratics. */
        for (int i = 0; i + 1 < m; i++) {
            double l = ux[i], r = ux[i + 1];
            if (r - l < EPS) continue;
            double mid = (l + r) * 0.5;
            double fl = f(p1, n1, p2, n2, l);
            double fm = f(p1, n1, p2, n2, mid);
            double fr = f(p1, n1, p2, n2, r);
            ans += (r - l) * (fl + 4.0 * fm + fr) / 6.0;
        }

        printf("%.10f\n", ans);
    }

    return 0;
}

