public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n1 = sc.nextInt();
        Point2D.Double[] poly1 = new Point2D.Double[n1];
        for (int i = 0; i < n1; i++) {
            poly1[i] = new Point2D.Double(sc.nextDouble(), sc.nextDouble());
        }
        int n2 = sc.nextInt();
        Point2D.Double[] poly2 = new Point2D.Double[n2];
        for (int i = 0; i < n2; i++) {
            poly2[i] = new Point2D.Double(sc.nextDouble(), sc.nextDouble());
        }

        // Collect all x coordinates from both polygons
        TreeSet<Double> xs = new TreeSet<>();
        for (Point2D.Double p : poly1) xs.add(p.x);
        for (Point2D.Double p : poly2) xs.add(p.x);

        double[] xArr = new double[xs.size()];
        int idx = 0;
        for (double v : xs) xArr[idx++] = v;

        double volume = 0.0;
        for (int i = 0; i < xArr.length - 1; i++) {
            double x0 = xArr[i];
            double x1 = xArr[i + 1];
            double mid = (x0 + x1) / 2.0;
            double yRange = ySpanAtX(poly1, mid);
            double zRange = zSpanAtX(poly2, mid);
            volume += yRange * zRange * (x1 - x0);
        }

        System.out.printf("%.10f%n", volume);
    }

    // get min and max y for given x in polygon (xy-plane)
    static double ySpanAtX(Point2D.Double[] poly, double x) {
        double minY = Double.MAX_VALUE;
        double maxY = -Double.MAX_VALUE;
        int n = poly.length;
        for (int i = 0; i < n; i++) {
            Point2D.Double a = poly[i];
            Point2D.Double b = poly[(i + 1) % n];
            if ((a.x <= x && b.x >= x) || (b.x <= x && a.x >= x)) {
                if (Math.abs(a.x - b.x) < 1e-12) {
                    if (Math.abs(a.x - x) < 1e-12) {
                        minY = Math.min(minY, Math.min(a.y, b.y));
                        maxY = Math.max(maxY, Math.max(a.y, b.y));
                    }
                } else {
                    double t = (x - a.x) / (b.x - a.x);
                    double y = a.y + t * (b.y - a.y);
                    minY = Math.min(minY, y);
                    maxY = Math.max(maxY, y);
                }
            }
        }
        return Math.max(0, maxY - minY);
    }

    // get min and max z for given x in polygon (xz-plane)
    static double zSpanAtX(Point2D.Double[] poly, double x) {
        double minZ = Double.MAX_VALUE;
        double maxZ = -Double.MAX_VALUE;
        int n = poly.length;
        for (int i = 0; i < n; i++) {
            Point2D.Double a = poly[i];
            Point2D.Double b = poly[(i + 1) % n];
            if ((a.x <= x && b.x >= x) || (b.x <= x && a.x >= x)) {
                if (Math.abs(a.x - b.x) < 1e-12) {
                    if (Math.abs(a.x - x) < 1e-12) {
                        minZ = Math.min(minZ, Math.min(a.y, b.y));
                        maxZ = Math.max(maxZ, Math.max(a.y, b.y));
                    }
                } else {
                    double t = (x - a.x) / (b.x - a.x);
                    double z = a.y + t * (b.y - a.y);
                    minZ = Math.min(minZ, z);
                    maxZ = Math.max(maxZ, z);
                }
            }
        }
        return Math.max(0, maxZ - minZ);
    }
}

import java.util.*;

public class Main {
    static double[] widthAtX(double[][] poly, double x) {
        int n = poly.length;
        double lo = Double.MAX_VALUE, hi = -Double.MAX_VALUE;
        boolean found = false;
        for (int i = 0; i < n; i++) {
            double x1 = poly[i][0], y1 = poly[i][1];
            double x2 = poly[(i+1)%n][0], y2 = poly[(i+1)%n][1];
            if (Math.min(x1,x2) <= x && x <= Math.max(x1,x2)) {
                double y;
                if (Math.abs(x2-x1) < 1e-12) y = (y1+y2)/2;
                else y = y1 + (y2-y1)*(x-x1)/(x2-x1);
                lo = Math.min(lo, y);
                hi = Math.max(hi, y);
                found = true;
            }
        }
        if (!found || hi < lo) return new double[]{0,0};
        return new double[]{lo, hi};
    }

    static double width(double[][] poly, double x) {
        double[] r = widthAtX(poly, x);
        return Math.max(0, r[1]-r[0]);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n1 = sc.nextInt(); if (n1 == 0) break;
            double[][] c1 = new double[n1][2];
            for (int i = 0; i < n1; i++) { c1[i][0]=sc.nextDouble(); c1[i][1]=sc.nextDouble(); }
            int n2 = sc.nextInt();
            double[][] c2 = new double[n2][2];
            for (int i = 0; i < n2; i++) { c2[i][0]=sc.nextDouble(); c2[i][1]=sc.nextDouble(); }

            double x1lo = Arrays.stream(c1).mapToDouble(p->p[0]).min().getAsDouble();
            double x1hi = Arrays.stream(c1).mapToDouble(p->p[0]).max().getAsDouble();
            double x2lo = Arrays.stream(c2).mapToDouble(p->p[0]).min().getAsDouble();
            double x2hi = Arrays.stream(c2).mapToDouble(p->p[0]).max().getAsDouble();
            double xlo = Math.max(x1lo, x2lo), xhi = Math.min(x1hi, x2hi);
            if (xlo >= xhi) { System.out.printf("%.6f%n", 0.0); continue; }

            TreeSet<Double> pts = new TreeSet<>();
            pts.add(xlo); pts.add(xhi);
            for (double[] p : c1) if (p[0]>xlo && p[0]<xhi) pts.add(p[0]);
            for (double[] p : c2) if (p[0]>xlo && p[0]<xhi) pts.add(p[0]);
            Double[] xs = pts.toArray(new Double[0]);
            double vol = 0;
            for (int i = 0; i+1 < xs.length; i++) {
                double a=xs[i], b=xs[i+1], m=(a+b)/2;
                double fa=width(c1,a)*width(c2,a), fm=width(c1,m)*width(c2,m), fb=width(c1,b)*width(c2,b);
                vol += (b-a)/6*(fa+4*fm+fb);
            }
            System.out.printf("%.6f%n", vol);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static final double EPS = 1e-10;

    // For a convex polygon, returns the vertical intersection length with line x = X.
    // Polygon is on (x,y)-plane.
    static double verticalWidth(Point[] poly, double X) {
        int n = poly.length;
        ArrayList<Double> ys = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            Point a = poly[i];
            Point b = poly[(i + 1) % n];

            double x1 = a.x, y1 = a.y;
            double x2 = b.x, y2 = b.y;

            if (Math.abs(x1 - x2) < EPS) {
                if (Math.abs(X - x1) < EPS) {
                    ys.add(y1);
                    ys.add(y2);
                }
                continue;
            }

            double minx = Math.min(x1, x2);
            double maxx = Math.max(x1, x2);

            if (X < minx - EPS || X > maxx + EPS) continue;

            double t = (X - x1) / (x2 - x1);
            if (t > -EPS && t < 1 + EPS) {
                double y = y1 + t * (y2 - y1);
                ys.add(y);
            }
        }

        if (ys.isEmpty()) return 0.0;

        double minY = ys.get(0), maxY = ys.get(0);
        for (double y : ys) {
            if (y < minY) minY = y;
            if (y > maxY) maxY = y;
        }
        return Math.max(0.0, maxY - minY);
    }

    static double areaFunction(Point[] c1, Point[] c2, double x) {
        return verticalWidth(c1, x) * verticalWidth(c2, x);
    }

    // Adaptive Simpson integration
    static double simpson(Point[] c1, Point[] c2, double l, double r) {
        double m = (l + r) * 0.5;
        return (areaFunction(c1, c2, l) + 4.0 * areaFunction(c1, c2, m) + areaFunction(c1, c2, r)) * (r - l) / 6.0;
    }

    static double adaptiveSimpson(Point[] c1, Point[] c2, double l, double r, double eps, double whole, int depth) {
        double m = (l + r) * 0.5;
        double left = simpson(c1, c2, l, m);
        double right = simpson(c1, c2, m, r);
        if (depth <= 0 || Math.abs(left + right - whole) <= 15.0 * eps) {
            return left + right + (left + right - whole) / 15.0;
        }
        return adaptiveSimpson(c1, c2, l, m, eps / 2.0, left, depth - 1)
             + adaptiveSimpson(c1, c2, m, r, eps / 2.0, right, depth - 1);
    }

    static double integrate(Point[] c1, Point[] c2, double l, double r) {
        if (r <= l + EPS) return 0.0;
        double whole = simpson(c1, c2, l, r);
        return adaptiveSimpson(c1, c2, l, r, 1e-8, whole, 25);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;

        StringBuilder out = new StringBuilder();

        while (first != null) {
            int n = Integer.parseInt(first);
            int m = fs.nextInt();

            if (n == 0 && m == 0) break;

            Point[] c1 = new Point[n];
            Point[] c2 = new Point[m];

            double minX1 = Double.POSITIVE_INFINITY, maxX1 = Double.NEGATIVE_INFINITY;
            double minX2 = Double.POSITIVE_INFINITY, maxX2 = Double.NEGATIVE_INFINITY;

            for (int i = 0; i < n; i++) {
                double x = fs.nextInt();
                double y = fs.nextInt();
                c1[i] = new Point(x, y);
                minX1 = Math.min(minX1, x);
                maxX1 = Math.max(maxX1, x);
            }

            for (int i = 0; i < m; i++) {
                double x = fs.nextInt();
                double z = fs.nextInt();
                c2[i] = new Point(x, z);
                minX2 = Math.min(minX2, x);
                maxX2 = Math.max(maxX2, x);
            }

            double l = Math.max(minX1, minX2);
            double r = Math.min(maxX1, maxX2);

            double ans = integrate(c1, c2, l, r);
            out.append(String.format(Locale.US, "%.10f%n", ans));

            first = fs.next();
        }

        System.out.print(out.toString());
    }
}

