const ld EPS = 1e-9;

struct Point {
    ld x, y;
    Point operator-(const Point& o) const { return {x - o.x, y - o.y}; }
};

ld cross(const Point& a, const Point& b) { return a.x * b.y - a.y * b.x; }

// Get min and max y for a given x in a convex polygon (assumes vertices in CCW order)
pair<ld,ld> getYRange(const vector<Point>& poly, ld x) {
    int n = poly.size();
    ld lo = 1e18, hi = -1e18;
    for (int i = 0; i < n; ++i) {
        const Point& a = poly[i];
        const Point& b = poly[(i+1)%n];
        if (min(a.x, b.x) - EPS <= x && x <= max(a.x, b.x) + EPS) {
            if (fabs(b.x - a.x) < EPS) {
                if (fabs(a.x - x) < EPS) {
                    lo = min(lo, min(a.y, b.y));
                    hi = max(hi, max(a.y, b.y));
                }
                continue;
            }
            ld t = (x - a.x) / (b.x - a.x);
            ld y = a.y + t * (b.y - a.y);
            lo = min(lo, y);
            hi = max(hi, y);
        }
    }
    return {lo, hi};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n1, n2;
    cin >> n1;
    vector<Point> c1(n1);
    for (auto& p : c1) cin >> p.x >> p.y;
    cin >> n2;
    vector<Point> c2(n2);
    for (auto& p : c2) cin >> p.x >> p.y;

    // Collect x breakpoints from both polygons
    vector<ld> xs;
    for (auto& p : c1) xs.push_back(p.x);
    for (auto& p : c2) xs.push_back(p.x);
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end(), [](ld a, ld b) { return fabs(a-b) < EPS; }), xs.end());

    ld volume = 0;
    for (size_t i = 0; i + 1 < xs.size(); ++i) {
        ld xl = xs[i], xr = xs[i+1];
        if (fabs(xr - xl) < EPS) continue;
        ld xm = (xl + xr) / 2;

        auto [y1l, y1r] = getYRange(c1, xm);
        auto [y2l, y2r] = getYRange(c2, xm);

        ld ylo = max(y1l, y2l);
        ld yhi = min(y1r, y2r);
        if (ylo > yhi + EPS) continue;

        // For each y in [ylo, yhi], the xz-plane cross-section: 
        // from c1: all z (since infinite along z)
        // from c2: at this x, we get a z-range from the polygon c2 (which is in xz-plane)
        // So area = z_range * (yhi - ylo)
        // Integrate over y => area(y) = z_range(y) * 1, but z_range doesn't depend on y,
        // so total volume = integrate z_range over y in [ylo,yhi] * dx

        // For c2 at x=xm: get z range (c2's y coordinate is actually z in 3D)
        auto [zlo, zhi] = getYRange(c2, xm);
        if (zlo > zhi + EPS) continue;

        ld area = (zhi - zlo) * (yhi - ylo);
        volume += area * (xr - xl);
    }

    cout << fixed << setprecision(10) << volume << "\n";
    return 0;
}

