#include <bits/stdc++.h>
using namespace std;

static const double EPS = 1e-12;

struct Point {
    double x, y;
};

double cross(const Point& a, const Point& b, const Point& c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

double polygonArea2(const vector<Point>& p) {
    double s = 0.0;
    int n = (int)p.size();
    for (int i = 0; i < n; ++i) {
        int j = (i + 1) % n;
        s += p[i].x * p[j].y - p[j].x * p[i].y;
    }
    return s;
}

double widthAtX(const vector<Point>& poly, double x) {
    vector<double> ys;
    int n = (int)poly.size();
    for (int i = 0; i < n; ++i) {
        Point a = poly[i], b = poly[(i + 1) % n];

        if (fabs(a.x - b.x) < EPS) {
            if (fabs(x - a.x) < 1e-10) {
                ys.push_back(a.y);
                ys.push_back(b.y);
            }
            continue;
        }

        double lx = min(a.x, b.x), rx = max(a.x, b.x);
        if (x + EPS < lx || x - EPS > rx) continue;

        double t = (x - a.x) / (b.x - a.x);
        if (t < -EPS || t > 1 + EPS) continue;
        double y = a.y + t * (b.y - a.y);
        ys.push_back(y);
    }

    if (ys.empty()) return 0.0;
    sort(ys.begin(), ys.end());
    return max(0.0, ys.back() - ys.front());
}

double simpson(const vector<Point>& A, const vector<Point>& B, double l, double r) {
    double m = (l + r) * 0.5;
    double fl = widthAtX(A, l) * widthAtX(B, l);
    double fm = widthAtX(A, m) * widthAtX(B, m);
    double fr = widthAtX(A, r) * widthAtX(B, r);
    return (r - l) * (fl + 4.0 * fm + fr) / 6.0;
}

