def polygon_slice(poly, x):
    """Returns (y_min, y_max) for the convex polygon at given x, or None if outside."""
    n = len(poly)
    ys = []
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i+1) % n]
        if (x1 <= x <= x2) or (x2 <= x <= x1):
            if x1 == x2:
                ys.extend([y1, y2])
            else:
                t = (x - x1) / (x2 - x1)
                ys.append(y1 + t * (y2 - y1))
    if len(ys) < 2:
        return 0.0
    return max(ys) - min(ys)

import sys
import math

EPS = 1e-10

def polygon_area(poly):
    s = 0.0
    n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        s += x1 * y2 - x2 * y1
    return 0.5 * s

def normalize_ccw(poly):
    if polygon_area(poly) < 0:
        poly.reverse()
    return poly

def x_interval_at(poly, x):
    ys = []
    n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]

        if abs(x1 - x2) < EPS:
            if abs(x - x1) < EPS:
                ys.append(y1)
                ys.append(y2)
            continue

        lo = min(x1, x2)
        hi = max(x1, x2)
        if x > lo + EPS and x < hi - EPS:
            t = (x - x1) / (x2 - x1)
            ys.append(y1 + t * (y2 - y1))
        elif abs(x - x1) < EPS:
            ys.append(y1)
        elif abs(x - x2) < EPS:
            ys.append(y2)

    if not ys:
        return 0.0, 0.0

    ys.sort()
    return ys[0], ys[-1]

def width_at(poly, x):
    a, b = x_interval_at(poly, x)
    return max(0.0, b - a)

def simpson(f, a, b):
    c = (a + b) * 0.5
    return (b - a) * (f(a) + 4.0 * f(c) + f(b)) / 6.0

def adaptive_simpson(f, a, b, eps, whole, depth):
    c = (a + b) * 0.5
    left = simpson(f, a, c)
    right = simpson(f, c, b)
    if depth <= 0 or abs(left + right - whole) <= 15.0 * eps:
        return left + right + (left + right - whole) / 15.0
    return (adaptive_simpson(f, a, c, eps * 0.5, left, depth - 1) +
            adaptive_simpson(f, c, b, eps * 0.5, right, depth - 1))

def integrate(f, a, b):
    if b - a < EPS:
        return 0.0
    whole = simpson(f, a, b)
    return adaptive_simpson(f, a, b, 1e-8, whole, 20)

def solve_dataset(poly1, poly2):
    poly1 = normalize_ccw(poly1)
    poly2 = normalize_ccw(poly2)

    xs1 = [p[0] for p in poly1]
    xs2 = [p[0] for p in poly2]

    L = max(min(xs1), min(xs2))
    R = min(max(xs1), max(xs2))

    if R <= L + EPS:
        return 0.0

    critical = [L, R]
    for x in xs1:
        if L + EPS < x < R - EPS:
            critical.append(x)
    for x in xs2:
        if L + EPS < x < R - EPS:
            critical.append(x)

    critical = sorted(set(round(x, 12) for x in critical))
    critical = [float(x) for x in critical]

    def f(x):
        return width_at(poly1, x) * width_at(poly2, x)

    ans = 0.0
    for i in range(len(critical) - 1):
        a = critical[i]
        b = critical[i + 1]
        if b - a < EPS:
            continue
        ans += integrate(f, a, b)

    return ans

